using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Configuration ──────────────────────────────────────────────────────────────
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var endpoint = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");

// ── Tools ──────────────────────────────────────────────────────────────────────
var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(SearchWeb, "search_web",
        "Search the web for a query and return a list of result snippets."),
    AIFunctionFactory.Create(notebook.TakeNote, "take_note",
        "Save a research note with a title and body."),
    AIFunctionFactory.Create(notebook.ReadNotes, "read_notes",
        "Return all notes taken so far."),
};

// ── Build agent ────────────────────────────────────────────────────────────────
var clientOptions = endpoint is not null
    ? new OpenAIClientOptions { Endpoint = new Uri(endpoint) }
    : new OpenAIClientOptions();

IChatClient chatClient = new OpenAIClient(apiKey, clientOptions)
    .GetChatClient(model)
    .AsIChatClient();

ChatClientAgent agent = chatClient.AsAIAgent(new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An AI research assistant that searches the web and takes notes.",
    ChatOptions = new() { Tools = [.. tools] },
});

// ── Run the conversation loop ──────────────────────────────────────────────────
Console.WriteLine("╔══════════════════════════════════════════════╗");
Console.WriteLine("║        Research Agent (type 'exit' to quit)  ║");
Console.WriteLine("╚══════════════════════════════════════════════╝");
Console.WriteLine();

var session = await agent.CreateSessionAsync();
var history = new List<ChatMessage>
{
    new(ChatRole.System,
        """
        You are a research assistant. When the user gives you a topic:
        1. Use the search_web tool to find relevant information (make multiple searches if needed).
        2. Use take_note to record key findings as you go.
        3. After gathering enough information, use read_notes to review your notes.
        4. Provide a well-structured summary to the user with key points and sources.
        Always cite your sources.
        """),
};

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("You > ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    history.Add(new(ChatRole.User, input));

    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.Write("Agent > ");
    Console.ResetColor();

    AgentResponse response = await agent.RunAsync(history, session);

    // Collect assistant messages produced during this turn.
    if (response.Messages is { } msgs)
    {
        foreach (var msg in msgs)
        {
            history.Add(msg);

            // Print only final text content (skip tool-call messages).
            if (msg.Role == ChatRole.Assistant)
            {
                var text = msg.Text;
                if (!string.IsNullOrWhiteSpace(text))
                    Console.WriteLine(text);
            }
        }
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// ── Tool implementations ───────────────────────────────────────────────────────

[Description("Search the web for a query and return a list of result snippets.")]
static async Task<string> SearchWeb(
    [Description("The search query to look up on the web.")] string query)
{
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"  🔍 Searching: {query}");
    Console.ResetColor();

    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "ResearchAgent/1.0 (Console; .NET 10)");

    try
    {
        // Use DuckDuckGo Instant Answer API (no key required).
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
        var doc = await http.GetFromJsonAsync<JsonElement>(url);

        var results = new List<string>();

        // Abstract text (main answer).
        var abstractText = doc.GetPropertyOrDefault("AbstractText");
        if (!string.IsNullOrWhiteSpace(abstractText))
            results.Add($"[Summary] {abstractText} (Source: {doc.GetPropertyOrDefault("AbstractURL")})");

        // Related topics.
        if (doc.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
        {
            foreach (var topic in topics.EnumerateArray().Take(8))
            {
                var text = topic.GetPropertyOrDefault("Text");
                var firstUrl = topic.GetPropertyOrDefault("FirstURL");
                if (!string.IsNullOrWhiteSpace(text))
                    results.Add($"- {text} ({firstUrl})");
            }
        }

        return results.Count > 0
            ? string.Join("\n", results)
            : $"No results found for '{query}'. Try rephrasing the query.";
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

// ── Notebook ───────────────────────────────────────────────────────────────────

sealed class Notebook
{
    private readonly List<(string Title, string Body)> _notes = [];

    [Description("Save a research note with a title and body.")]
    public string TakeNote(
        [Description("Short title for the note.")] string title,
        [Description("The note content.")] string body)
    {
        _notes.Add((title, body));
        Console.ForegroundColor = ConsoleColor.DarkGray;
        Console.WriteLine($"  📝 Note saved: {title}");
        Console.ResetColor();
        return $"Note '{title}' saved (total notes: {_notes.Count}).";
    }

    [Description("Return all notes taken so far.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Body}"));
    }
}

// ── Helpers ────────────────────────────────────────────────────────────────────

static class JsonElementExtensions
{
    public static string GetPropertyOrDefault(this JsonElement element, string propertyName)
    {
        if (element.TryGetProperty(propertyName, out var value) && value.ValueKind == JsonValueKind.String)
            return value.GetString() ?? string.Empty;
        return string.Empty;
    }
}

