using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Configuration ──────────────────────────────────────────────────────────────
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var endpoint = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");

// ── Tools ──────────────────────────────────────────────────────────────────────
var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(SearchWeb, "search_web",
        "Search the web for a query and return a list of result snippets."),
    AIFunctionFactory.Create(notebook.TakeNote, "take_note",
        "Save a research note with a title and body."),
    AIFunctionFactory.Create(notebook.ReadNotes, "read_notes",
        "Return all notes taken so far."),
};

// ── Build agent ────────────────────────────────────────────────────────────────
var clientOptions = endpoint is not null
    ? new OpenAIClientOptions { Endpoint = new Uri(endpoint) }
    : new OpenAIClientOptions();

IChatClient chatClient = new OpenAIClient(apiKey, clientOptions)
    .GetChatClient(model)
    .AsIChatClient();

ChatClientAgent agent = chatClient.AsAIAgent(new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An AI research assistant that searches the web and takes notes.",
    ChatOptions = new() { Tools = [.. tools] },
});

// ── Run the conversation loop ──────────────────────────────────────────────────
