     http.DefaultRequestHeaders.UserAgent.ParseAdd(
         "ResearchAgent/1.0 (Console; .NET 10)");

     try
     {
         // Use DuckDuckGo Instant Answer API (no key required).
         var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
         var doc = await http.GetFromJsonAsync<JsonElement>(url);

         var results = new List<string>();

         // Abstract text (main answer).
         var abstractText = doc.GetPropertyOrDefault("AbstractText");
         if (!string.IsNullOrWhiteSpace(abstractText))
             results.Add($"[Summary] {abstractText} (Source: {doc.GetPropertyOrDefault("AbstractURL")})");

         // Related topics.
         if (doc.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
         {
             foreach (var topic in topics.EnumerateArray().Take(8))
             {
                 var text = topic.GetPropertyOrDefault("Text");
                 var firstUrl = topic.GetPropertyOrDefault("FirstURL");
                 if (!string.IsNullOrWhiteSpace(text))
                     results.Add($"- {text} ({firstUrl})");
             }
         }

         return results.Count > 0
             ? string.Join("\n", results)
             : $"No results found for '{query}'. Try rephrasing the query.";
     }
     catch (Exception ex)
     {
         return $"Search failed: {ex.Message}";
     }
 }

 // ── Notebook ───────────────────────────────────────────────────────────────────

 sealed class Notebook
 {
     private readonly List<(string Title, string Body)> _notes = [];

     [Description("Save a research note with a title and body.")]
     public string TakeNote(
         [Description("Short title for the note.")] string title,
         [Description("The note content.")] string body)
     {
         _notes.Add((title, body));
         Console.ForegroundColor = ConsoleColor.DarkGray;
         Console.WriteLine($"  📝 Note saved: {title}");
         Console.ResetColor();
         return $"Note '{title}' saved (total notes: {_notes.Count}).";
     }

     [Description("Return all notes taken so far.")]
     public string ReadNotes()
     {
         if (_notes.Count == 0)
             return "No notes taken yet.";

         return string.Join("\n\n", _notes.Select((n, i) =>
             $"--- Note {i + 1}: {n.Title} ---\n{n.Body}"));
     }
 }

 // ── Helpers ────────────────────────────────────────────────────────────────────

 static class JsonElementExtensions
 {
     public static string GetPropertyOrDefault(this JsonElement element, string propertyName)
     {
         if (element.TryGetProperty(propertyName, out var value) && value.ValueKind == JsonValueKind.String)
             return value.GetString() ?? string.Empty;
         return string.Empty;
     }
 }
